"""Form Five Economics Term One, including guided practical rows, including guided preparation.
Original cases; current legal filing rules, investment returns and real company statistics are not assumed.
"""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_en as B
from lessonlib import card,worked,learn,num
L.use_class("form-5","Form 5")
OUT=L.ROOT/"economics"
PATH=[]
SRC=["money"]

def F(term,meaning,case,error,why):
    return dict(term=term,meaning=meaning,case=case,error=error,why=why)

def qa(n,key,level,items):
    return B.QA(f"n5-{n}-{key}",level,"{X.q}",items,SRC)

def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)

def number(n,key,prompt,answer,vars,steps,misc,where=(),level=2,unit="CFA francs"):
    return num(f"n5-{n}-{key}",level,prompt,answer,steps,vars=vars,misc=misc,where=list(where),unit=unit,sources=SRC)

def lesson(n,title,goal,back,next_use,note,case,method,facts,applied,example=None,prereq=(),questions=None,figure=None):
    assert len(facts)==4
    defs=[]; cases=[]; reasons=[]
    for i,f in enumerate(facts):
        other=[x for j,x in enumerate(facts) if j!=i]
        defs.append(item("Which term means "+f["meaning"]+"?",f["term"],[(x["term"],x["term"]+" concerns "+x["meaning"]+", rather than the concept asked for.") for x in other],f["meaning"].capitalize()+"."))
        cases.append(item(f["case"]+"\nWhich concept best explains the highlighted feature?",f["term"],[(x["term"],"That concerns "+x["meaning"]+". This case instead concerns "+f["meaning"]+".") for x in other],f["why"]))
        reasons.append(item(f["case"]+"\nWhich explanation is appropriate?",f["why"],[(x["why"],"That explanation addresses "+x["term"]+", rather than the feature described here.") for x in other],f["meaning"].capitalize()+"."))
    q0=qa(n,"terms",1,defs); q1=qa(n,"cases",1,cases); q2=qa(n,"reasons",2,reasons)
    q4=B.SP(f"n5-{n}-repair",3,"Find the incorrect economic claim.",
        [f["term"]+": "+f["meaning"]+"." for f in facts],[(f["error"],f["why"]) for f in facts],SRC)
    for st,f in zip(q4["pool"]["right"],facts):
        st["explain"]="This is correct: "+f["meaning"]+". Look for a statement that contradicts the lesson’s distinction."
    qs=questions or [q0,q1,q2,applied,q4]
    # The case card teaches all banked cases, not an unrelated example for its random check.
    cards=[card(f"n5-{n}-c1","Distinguish the monetary concepts before evaluating a case.",[f["term"]+": "+f["meaning"]+"." for f in facts],q0["id"]),
       card(f"n5-{n}-c2","Use the stated case evidence to identify the economic feature.",[f["case"] for f in facts],q1["id"]),
       card(f"n5-{n}-c3","Explain a consequence instead of assuming every option has the same effect.",[f["term"]+": "+f["why"] for f in facts],{**q2,"id":f"n5-{n}-reasons-card","level":1})]
    if questions:
        # Practical cards retain the concepts above, with their own consistent checks.
        cards[0]["check"]={**q0,"id":f"n5-{n}-terms-card"}
        cards[1]["check"]={**q1,"id":f"n5-{n}-cases-card"}
    sections=[("Your goal and connections","By the end, you should be able to "+goal+". Builds on: "+back+". Leads to: "+next_use+"."),
       ("Understand the economics",note),("Follow the local case",case),("Reason and check",method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson("economics","economics",n,(f"n5-{n}",title),prereq,note,
       example or worked({},facts[0]["case"]+" Explain the feature.",[facts[0]["meaning"].capitalize()+".",facts[0]["why"]],facts[0]["term"]),
       cards,qs,learn=learn(sections,key_words=[(f["term"],f["meaning"]) for f in facts],
       mistake=(facts[0]["error"],facts[0]["term"]+": "+facts[0]["meaning"]+".",facts[0]["why"])))
    PATH.append((n,title,goal,back,next_use))

def choose(n,rows,key="apply",level=2):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows])

lesson(1,'Money: functions and the limits of barter','distinguish money’s functions and explain how a medium of exchange reduces a barter obstacle',
 'Form Four trade, production and exchange','qualities of money, money demand and purchasing power',
 'Money is an asset broadly accepted for payment in its community. As a medium of exchange it separates selling from buying, reducing the need to find someone who simultaneously wants what the seller offers. As a unit of account it expresses comparable prices. As a store of value it carries purchasing ability over time, though inflation can erode that ability. Money can also express deferred payments. A useful object or a payment instruction is not automatically money.',
 'In a fictional Bamenda market, a notebook seller wants vegetables but the vegetable seller does not want notebooks. An accepted currency can separate the exchanges. Prices quoted in CFA francs also give a common accounting unit. Holding a cash balance for later does not guarantee its future purchasing power.',
 'Identify the particular obstacle or function in the case. Separate the thing being paid from an instruction to transfer it. Do not confuse money with all wealth or assume every valuable item is readily accepted in payment.',[
 F('medium of exchange','an accepted intermediary used in payment','The market sellers use accepted currency rather than matching wants.','Barter always requires no matching of wants.','Direct barter can require a double coincidence of wants.'),
 F('unit of account','a common measure for expressing prices and debts','Both sellers quote prices in CFA francs.','A common price unit guarantees identical prices for every good.','It allows comparison, not identical valuations.'),
 F('store of value','a way of carrying purchasing ability over time','A seller retains a money balance for a later purchase.','Money’s purchasing power can never change.','Price changes can alter what a fixed balance buys.'),
 F('standard of deferred payment','a unit for stating an obligation payable later','A fictional agreement names a future payment in CFA francs.','A future nominal amount guarantees an unchanged real burden.','The real burden can change with the price level.')],choose(1,[
 ('Why can accepted currency help when the vegetable seller does not want notebooks?','It separates the sale from the later purchase.',['It makes all goods equally priced.','It eliminates every production cost.','It guarantees no price changes.'],['A common medium does not equalise prices.','Exchange does not remove production costs.','Money does not guarantee stable prices.'],'The sellers no longer need matching immediate wants.'),
 ('A pupil compares folder and notebook prices in CFA francs. Which function is central?','Unit of account.',['Store of value only.','Physical durability.','An instruction to transfer a deposit.'],['The case is a price comparison, not retaining balances.','Durability is a quality, not this comparison function.','No payment instruction is described.'],'The common unit permits comparison.'),
 ('A seller keeps a balance for next week. What qualification is needed?','Its later purchasing power may change.',['It becomes worthless by definition overnight.','It must buy exactly the same basket forever.','It proves the seller owns no other wealth.'],['A possibility of change is not inevitable worthlessness.','Price changes can alter the basket.','A money balance says nothing complete about other assets.'],'Store of value is not a guarantee of constant real value.'),
 ('Which distinction is correct?','A cheque instructs payment from a deposit; it is not identical to the deposit balance.',['A cheque is necessarily central-bank cash.','Every valuable machine is immediately money.','A price label is itself a paid debt.'],['A cheque is a payment instrument.','Valuable wealth need not be broadly accepted in payment.','A label states a price rather than paying it.'],'Separate money, wealth and payment instructions.')]))

lesson(2,'Money: qualities, forms and acceptance','compare useful qualities of money and distinguish cash, deposits and payment instruments',
 'money’s functions and barter','money demand, supply and banking',
 'Useful money is generally acceptable, recognisable, durable, portable and divisible into workable units. These qualities help it perform functions but do not alone make every object money. Commodity money has a non-monetary commodity use; fiat currency does not depend on an equivalent commodity content. Banknotes and coins differ from transferable bank deposits. A card or cheque may instruct payment using a balance without being that balance itself. This is an economic distinction, not a guide to opening accounts or identifying counterfeits.',
 'A fictional market compares a bulky perishable crop with an accepted currency for small payments. Divisibility and durability can help explain the choice. In Cameroon the BEAC issues the common Central African CFA currency; deposit balances at commercial banks are a different form of monetary claim. A payment card accesses an account rather than storing every payment as physical notes.',
 'Separate a quality from a function and a form from its payment instrument. Explain why a quality helps exchange without assuming that it guarantees acceptance everywhere. Ask which institution owes or issues the monetary claim.',[
 F('divisibility','the ability to use practical smaller payment units','Small denominations can help settle a modest purchase.','Divisibility means every good must be cut physically.','The payment units, not necessarily goods, are divided.'),
 F('durability','the ability to remain usable through ordinary handling over time','A perishable crop may be inconvenient to retain for later exchange.','Durability means money can never lose purchasing power.','Physical usability differs from real value.'),
 F('fiat currency','currency whose monetary use does not require equivalent commodity content','A note’s payment role is not determined by its paper value.','Every note must contain its face value in a precious metal.','Fiat currency is not defined by equivalent intrinsic metal value.'),
 F('deposit money','a transferable monetary claim on a bank','A payment transfers a customer’s deposit balance.','A payment card is identical to the bank’s entire deposit liability.','The instrument and the underlying claim differ.')],choose(2,[
 ('Why is a rapidly spoiling item inconvenient as a store for later exchange?','Its physical usefulness may deteriorate.',['It is too divisible by definition.','It must be a bank deposit.','Its spoilage guarantees falling national prices.'],['Divisibility is a separate quality.','A crop is not thereby a deposit.','One item’s deterioration establishes no price-level trend.'],'Durability helps retention.'),
 ('A note’s paper has little commodity value. Does that alone prevent fiat monetary use?','No; acceptance and the monetary framework matter.',['Yes; all money must be gold.','Yes; paper can never communicate a denomination.','No; therefore every piece of paper is money.'],['Commodity content is not required for fiat currency.','Printed denominations can communicate units.','Not every paper is accepted currency.'],'Low paper value does not determine monetary acceptability.'),
 ('Which pair distinguishes balance from instrument?','Deposit balance and payment card.',['Two names for the same physical coin.','Commodity value and rainfall.','Every machine and every cheque.'],['The pair concerns a claim and its access instrument.','That is not the stated monetary distinction.','Wealth and instructions are not automatically money.'],'A card can instruct use of a balance.'),
 ('Why can small denominations be useful?','They allow practical payment of smaller sums.',['They guarantee every buyer receives a loan.','They make all goods free.','They eliminate the need for acceptance.'],['Denominations do not guarantee credit.','A payment still has value.','Acceptance remains relevant.'],'This illustrates divisibility.')]),prereq=[1])

lesson(3,'Demand for and supply of money','explain why balances are held and distinguish a money stock from income flows',
 'money forms and functions','value of money, inflation and bank deposit creation',
 'Demand for money means the balances people wish to hold, not every desire for higher income. Transactions balances support expected payments; precautionary balances address uncertainty. Portfolio choice also compares liquid money with other assets, taking risk, liquidity and the opportunity cost of forgone returns into account. Money supply is a defined stock at a point in time. Its measure depends on which currency and deposit categories are included. Do not add a flow of annual income to a money stock as if they measured the same thing.',
 'An imaginary Buea trader keeps a balance for routine suppliers and a separate cushion for uncertain expenses. Another household compares a liquid balance with a less liquid asset. These cases explain motives without prescribing a financial choice. The class counts a narrowly defined money stock comprising currency held by the public and specified transferable deposits, avoiding double counting bank vault cash.',
 'Identify whether a figure is a stock at a date or a flow during a period. For demand, name the reason for holding balances. State the definition before adding components; the lesson supplies no actual Cameroon monetary total or current interest rate.',[
 F('transactions motive','holding balances for expected payments','The trader retains money for routine supplier payments.','Demand for money means wishing to buy every possible good.','It concerns desired holdings, not unlimited wants.'),
 F('precautionary motive','holding balances against uncertain needs','A household keeps a cushion for an unexpected expense.','Every unplanned expense is already a known scheduled bill.','Uncertainty distinguishes this case from routine transactions.'),
 F('opportunity cost','the forgone alternative associated with holding liquid balances','A person compares liquidity with possible returns on another asset.','Holding money has no possible forgone alternative.','A relevant alternative can make holding balances costly.'),
 F('money stock','a defined monetary quantity measured at a time','The class counts specified currency and deposits on one date.','A year’s income is automatically a stock measured at one instant.','Income per period is a flow.')],number(3,'stock','In an invented narrow measure, public currency is {c} CFA francs and included transferable deposits are {d}. They do not overlap. Find the money stock.','c+d',
 {'u':{'int':[2,9]},'v':{'int':[10,30]},'c':{'expr':'u*1000'},'d':{'expr':'v*1000'}},['Use only the categories included in this defined stock.','{c} + {d} = {answer} CFA francs.'],[('currency','c','That omits the included deposit balances.'),('difference','d-c','The non-overlapping included categories are added, not netted against each other.')]),prereq=[1,2])

power=number(4,'power','A fictional fixed basket cost {base} CFA francs in the base period and costs {now} now. What is the present purchasing-power index of a fixed money unit relative to base {100}?','100*base/now',
 {'u':{'int':[2,8]},'k':{'pick':[2,4,5]},'base':{'expr':'u*1000'},'now':{'expr':'base*k/2'}},['The price index is {100*now/base}.','The reciprocal purchasing-power index is {100} × {base}/{now} = {answer}.'],[('priceindex','100*now/base','That is the price index; purchasing power moves inversely.'),('change','100*(now-base)/base','That is a price-change percentage, not the requested level index.')],where=['now!=base'],unit='index points')
lesson(4,'The value of money','distinguish internal purchasing power from external exchange value and calculate a reciprocal index',
 'money stock, transactions and comparable units','basket practical and inflation measurement',
 'Internal value is purchasing power over goods and services. For a fixed amount of money, a higher comparable price level means less purchasing power. A price index compares the cost of the same defined basket with its base cost. A purchasing-power index relative to the same base is the reciprocal price ratio scaled to the base. External value concerns exchange against another currency; it is not the same measurement. These exercises use invented baskets and no current exchange rate.',
 'Original basket: base cost {2000} CFA francs; later cost {2500}. The price index is {100*2500/2000}. The purchasing-power index of a fixed unit is {100*2000/2500}. The higher price index does not mean the fixed balance buys more. This basket is a teaching model, not a national consumer-price series.',
 'Keep basket composition fixed and label which index is requested. Divide later by base for prices and base by later for purchasing power, then scale. Do not confuse an index level with a percentage change or infer an exchange rate from an internal price index.',[
 F('internal value','purchasing power over a specified goods-and-services basket','A fixed balance buys less when the same basket costs more.','Higher basket prices always increase a fixed balance’s purchasing power.','The same money then covers less of the basket.'),
 F('price index','a scaled comparison of current and base basket cost','Divide later basket cost by base cost and scale.','A price index directly gives a current foreign-exchange rate.','A basket comparison and an exchange quotation differ.'),
 F('purchasing-power index','the reciprocal price ratio scaled to the common base','Divide base basket cost by later cost and scale.','Price and purchasing-power indices always rise together.','They move inversely for this fixed-basket model.'),
 F('external value','exchange value against another currency','An exchange quotation compares currency units.','An internal basket index alone establishes external exchange value.','A separate exchange comparison is needed.')],power,prereq=[1,3])

def record_table(label,rows):
    height=50+len(rows)*29
    bits=[json.dumps(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 {height}" role="img" aria-label="{label}"><rect width="320" height="100%" fill="#f2f3ee"/><g font-family="sans-serif" font-size="14" fill="#213b2d"><text x="10" y="23">Classroom model - CFA francs</text>')]
    for i,(name,expr) in enumerate(rows):
        y=52+i*29
        bits += [json.dumps(f'<text x="10" y="{y}">{name}</text><text x="309" y="{y}" text-anchor="end">'),f'fmt({expr})',json.dumps('</text>')]
    bits.append(json.dumps('</g></svg>'))
    return ' + '.join(bits)

basket=number(5,'basket','Invented fixed basket: {q} notebooks at {p} CFA francs each in the base period, now {np} each; and {k} folders at {f} each in the base period, now {nf} each. Find the later cost of the same basket.','q*np+k*nf',
 {'q':{'int':[2,5]},'k':{'int':[1,4]},'p':{'pick':[100,200,300]},'f':{'pick':[400,500,600]},'np':{'expr':'p+50'},'nf':{'expr':'f+100'}},
 ['Keep the quantities fixed rather than replacing the basket.','Later cost = {q} × {np} + {k} × {nf} = {answer} CFA francs.'],[('base','q*p+k*f','That uses the old prices rather than the later prices.'),('unweighted','np+nf','That adds unit prices without multiplying by the stated quantities.')])
lesson(5,'Practical preparation: a fixed-basket record','record comparable quantities and costs and explain what a small basket can establish',
 'internal purchasing power and price indices','inflation measurement and careful comparisons',
 'Use an invented basket or teacher-supplied observations; no shopping or personal spending is required. Record item, unit, fixed quantity, base unit price and later unit price. Multiply quantity by unit price and add item costs in each period. Hold composition and quality constant for this model. A small classroom basket describes itself; it is not automatically representative of Cameroon’s national price level. Mark any missing quotation rather than inventing a price.',
 'Original basket: {2} notebooks at {200} then {250} CFA francs each; {1} folder at {600} then {650}. Base cost is {2*200+600}; later cost is {2*250+650}. Price index is {100*(2*250+650)/(2*200+600)}. The comparison preserves quantities, units and quality. It does not measure the experience of every household.',
 'Prepare the item record, calculate both totals and label the base. Check missing observations and comparable units. Explain the difference between a particular basket’s movement and a representative price index. A different basket needs its own weights and evidence.',[
 F('fixed quantity','an unchanged amount of each item across the comparison','The same notebook count is used in both periods.','Changing quantities without explanation isolates only price movement.','A changed basket mixes quantity and price effects.'),
 F('item cost','quantity multiplied by comparable unit price','Notebook count multiplies price per notebook.','Adding quantities to currency prices gives an item cost.','The quantities multiply matching unit prices.'),
 F('basket total','the sum of the included item costs','Notebook and folder costs are added within the same period.','Adding the base and later totals gives the later basket cost.','The periods need separate totals.'),
 F('representativeness limit','the scope restriction of a small chosen basket','This stationery basket does not measure every household’s inflation.','Any classroom basket is automatically the official national index.','A national measure needs a defined representative method.')],basket,prereq=[4],figure=record_table('Invented fixed stationery basket totals',[('Base notebooks','2*200'),('Base folder','600'),('Base total','2*200+600'),('Later notebooks','2*250'),('Later folder','650'),('Later total','2*250+650')]))

inflation=number(6,'rate','A fictional comparable price index rises from {old} to {new} over the stated period. Calculate the percentage change.','100*(new-old)/old',
 {'old':{'pick':[100,120,150,200]},'r':{'pick':[2,4,5,10]},'new':{'expr':'old*(1+r/100)'}},['Change = later minus earlier index.','Divide by earlier: {100} × ({new} − {old})/{old} = {answer}%.'],
 [('difference','new-old','That is an index-point change, not generally a percentage of the earlier level.','old!=100'),('newbase','100*(new-old)/new','The requested percentage uses the earlier index as denominator.')],unit='%')
lesson(6,'Inflation: meaning and measurement','calculate a price-index change and distinguish general inflation from a single price movement',
 'basket records, indices and purchasing power','causes, effects and the distinction from deflation',
 'Inflation is a sustained rise in the general price level. A consumer-price measure tracks a defined basket with weights reflecting a specified method. An individual price can rise while others fall, so its movement alone does not establish general inflation. Calculate a period’s percentage index change using the earlier index as denominator. A change in index points is not automatically the same numerical percentage. The fictional indices here teach arithmetic; they are not current Cameroon inflation statistics.',
 'Original index: {120} rises to {126}. The change is {126-120} index points, while the percentage change is {100*(126-120)/120}%. A stationery price alone cannot establish that all national prices rose at that rate. Nor does a lower inflation rate necessarily mean falling prices.',
 'Identify the periods and index method, subtract earlier from later and divide by earlier before multiplying by {100}. Label percentage and index points separately. Check whether the evidence describes one item or a broader price measure.',[
 F('inflation','a sustained increase in the general price level','A broad comparable price index rises over time.','Any single shop’s price rise proves national inflation of the same size.','One price does not establish the broad measure.'),
 F('basket weight','an item’s contribution under the index method','A frequently purchased item may receive a greater expenditure weight.','Every possible index must weight each item equally.','Weights depend on the defined measure.'),
 F('index-point change','the arithmetic difference between index levels','Subtract earlier from later index.','An index-point difference is always the same numerical percentage.','Percentage change also depends on the earlier level.'),
 F('percentage inflation rate','the index change relative to its earlier level','Divide the change by the earlier index and scale.','Always divide the change by the later index.','The earlier level is the reference for this change.')],inflation,prereq=[4,5])

lesson(7,'Inflation: causes, effects and policy choices','connect a stated inflation pressure to a mechanism and explain a conditional effect',
 'price-index changes and nominal versus real value','deflation and central-bank policy',
 'Demand-pull pressure can arise when spending grows faster than productive capacity. Cost-push pressure can arise from higher input costs or disrupted supply. Expectations can influence wage and price decisions. These mechanisms may interact; one example does not identify every cause. Unanticipated inflation can reduce the real value of fixed nominal balances and change the real burden of fixed nominal debts. Outcomes depend on income adjustment, contract terms and policy response. Measures restraining demand can have output costs and do not directly repair every supply disruption.',
 'In a fictional case, transport disruption raises costs across several producers while another case describes spending pressing against limited capacity. The first illustrates a supply pressure; the second a demand pressure. A household’s unchanged nominal cash balance buys less if its relevant basket costs more. No current inflation forecast or investment choice is supplied.',
 'Name the stated change, trace a plausible mechanism and qualify the conclusion. Separate a nominal amount from its real purchasing ability. Match a proposed policy to the pressure, recognising time lags and trade-offs rather than promising an immediate cure.',[
 F('demand-pull pressure','spending growth pressing beyond available productive capacity','Broad spending rises while output capacity cannot keep pace.','Any demand increase must cause the same inflation whatever unused capacity exists.','Capacity and supply response affect the outcome.'),
 F('cost-push pressure','upward price pressure from higher costs or supply disruption','Transport disruption raises input costs across producers.','A supply disruption is by definition a rise in productive capacity.','It can reduce availability or raise costs instead.'),
 F('real-value effect','a change in purchasing ability despite a fixed nominal amount','Unchanged cash covers less of a more expensive basket.','An unchanged numeral guarantees unchanged real value.','Prices affect purchasing ability.'),
 F('policy trade-off','a policy benefit considered with costs and limits','Demand restraint may reduce pressure while slowing activity.','Any anti-inflation measure removes every cause instantly without cost.','Mechanisms, delays and side effects matter.')],choose(7,[
 ('Spending rises against already limited broad capacity. Which pressure is described?','Demand-pull pressure.',['A guaranteed increase in every resource.','A complete absence of demand.','A measurement of one bank’s equity.'],['Capacity does not automatically expand.','The case specifies rising spending.','No balance sheet is supplied.'],'Demand is pressing against capacity.'),
 ('Transport disruption raises costs for many producers. Which mechanism fits?','Cost-push pressure.',['A proof of falling input costs.','A guarantee that every nominal income rises equally.','A universal improvement in supply.'],['Costs are stated to rise.','No equal income adjustment is supplied.','Supply is disrupted.'],'The pressure begins with costs and supply.'),
 ('Cash stays nominally fixed while its basket costs more. What follows in this comparison?','The balance’s purchasing power falls.',['Its purchasing power necessarily rises.','Its numeral must double.','It proves every borrower benefits equally.'],['A dearer basket means less buying ability.','The amount is explicitly fixed.','Debt terms and adjustment differ.'],'Distinguish real value from the nominal amount.'),
 ('Why may demand restraint have a trade-off?','It can restrain spending while also slowing activity.',['It directly restores every damaged supply route.','It always acts instantly.','It guarantees no output effects.'],['Demand restraint is not physical route repair.','Policy effects can take time.','Output costs are possible.'],'Match the mechanism and its limits.')]),prereq=[6])

lesson(8,'Deflation and disinflation','distinguish a falling price level from a slowing rise and explain a possible consequence',
 'inflation rates, purchasing power and nominal debt','banking and the monetary-policy role',
 'Deflation is a sustained fall in the general price level; disinflation is a reduction in the inflation rate. Prices can keep rising during disinflation when the rate remains positive. A single discounted item is not enough to establish general deflation. Persistent deflation can increase the real burden of a fixed nominal debt and may accompany weak spending and employment, though effects depend on the cause and wider conditions. A productivity-led relative price fall differs from a broad, prolonged demand contraction.',
 'Original comparison: an inflation rate slows from {8}% to {3}% while remaining positive, so the general price level still rises. A comparable broad index falling from {100} to {96} instead records a {100*(96-100)/100}% movement. The first is disinflation; a sustained general decline is deflation.',
 'Look at the price level as well as the rate of change. Ask whether the measure is broad and the decline sustained. Do not turn a higher purchasing power of fixed cash into a guarantee that every household is better off when income or employment may also change.',[
 F('deflation','a sustained fall in the general price level','A broad price measure declines persistently.','Every price discount establishes general deflation.','One item is not the general price level.'),
 F('disinflation','a fall in the rate of inflation','Positive inflation slows while prices keep rising.','A lower positive inflation rate means the price level must fall.','A positive rate still means an increase.'),
 F('real debt burden','the purchasing-value burden of a fixed nominal repayment','Falling prices can make a fixed repayment larger in real terms.','A fixed nominal debt automatically vanishes during deflation.','The nominal obligation remains in this model.'),
 F('conditional welfare effect','recognition that price changes interact with income and work','Cheaper goods do not prove everyone benefits if incomes fall too.','Falling prices guarantee every person is better off.','Income, debt and employment outcomes also matter.')],choose(8,[
 ('Inflation slows from {8}% to {3}% and remains positive. Which description fits?','Disinflation with prices still rising.',['Deflation with prices falling.','An unchanged price level.','A guarantee of rising real wages.'],['Both stated rates are positive.','The later positive rate still raises prices.','No wage information is supplied.'],'Slower increases are not decreases.'),
 ('A general price level falls persistently. Which description fits?','Deflation.',['Positive inflation by definition.','Only a reduction in a still-positive rate.','A guaranteed improvement for every debtor.'],['The direction is downward.','The price level itself falls.','Fixed nominal debts can become heavier in real terms.'],'Use the level direction and persistence.'),
 ('A shop discounts one notebook. What can be concluded about general deflation?','The single observation is insufficient.',['General deflation is proved.','All wages must fall.','All other prices must be unchanged.'],['A single item is not the general measure.','No wage data are supplied.','Other prices are unknown.'],'Keep the evidence’s scope.'),
 ('Why may fixed nominal debt become harder to bear during broad deflation?','Its repayment can represent more purchasing value.',['Its nominal amount must become zero.','The lender loses all claims by definition.','Every borrower’s income is guaranteed to rise.'],['The nominal amount is fixed in the case.','No such cancellation rule is supplied.','Income can move differently.'],'The real burden can rise without a nominal increase.')]),prereq=[6,7])

lesson(9,'Fundamental notions of banking','explain deposit-taking, payments and lending while distinguishing liquidity and credit risk',
 'money forms, desired balances and real value','commercial-bank functions and the bank balance sheet',
 'A bank provides deposit and payment services and extends credit. It brings financial relationships together, assesses borrowers and manages risks, rather than merely storing every customer’s deposit as labelled notes. A customer’s deposit is a claim on the bank. A loan granted by the bank is its claim on the borrower. Liquidity concerns meeting payments when due; credit risk concerns failure to repay. These can interact but are not the same. The lesson describes economic functions without recommending any institution or announcing account rules.',
 'An imaginary bank serves a Bamenda trader receiving deposits and paying suppliers. Another customer borrows for a stated purpose. The bank must consider repayment and settlement needs. A sound-looking loan may not be immediately convertible into cash for a payment; a failed borrower may reduce the value of the bank’s assets.',
 'Identify who owes whom. Separate a deposit claim, a loan claim and a payment service. Ask whether a difficulty concerns timing of liquid funds or loss from non-repayment. Do not infer that a profitable-looking bank can ignore payment needs.',[
 F('deposit-taking','accepting balances owed by the bank to customers','A customer holds a claim recorded in an account.','Every deposit is a share of ownership in the bank.','A deposit claim differs from an equity stake.'),
 F('payment service','arranging transfers to settle obligations','The trader transfers a balance to pay a supplier.','Every transfer necessarily creates a new loan.','A transfer can move an existing balance.'),
 F('liquidity risk','the risk of being unable to meet payments when due','Assets may exist without enough immediately available settlement funds.','Having assets guarantees every immediate payment can be met.','Timing and liquid availability matter.'),
 F('credit risk','the risk that a borrower fails to repay as agreed','A default reduces the expected value of a loan claim.','Credit risk means the printer has run out of paper.','It concerns repayment, not office supplies.')],choose(9,[
 ('From the bank’s perspective, who owes a customer deposit?','The bank owes the customer.',['The customer necessarily owes the deposit to the bank.','The customer becomes the central bank.','Nobody has any claim.'],['That reverses the liability relationship.','Holding a deposit changes no institutional identity.','The balance is a claim.'],'Deposits are bank liabilities.'),
 ('A loan is not repaid as agreed. Which risk is illustrated?','Credit risk.',['Divisibility.','A guaranteed capital gain.','An index base change only.'],['Divisibility is a money quality.','Non-repayment can cause loss.','No price index is supplied.'],'The problem concerns repayment.'),
 ('A bank has long-term claims but lacks funds for a payment due now. Which issue is central?','Liquidity.',['An automatic absence of all assets.','The definition of a banknote.','A proof that no customer exists.'],['The case explicitly supplies assets.','It concerns payment timing.','No such absence is implied.'],'Existing assets may be insufficiently liquid.'),
 ('Why distinguish a deposit from an ownership share?','A deposit is a claim owed to a customer; equity is a residual ownership interest.',['Both must be the same physical note.','Every customer controls the bank.','An account balance proves a guaranteed dividend.'],['They are different claims, not necessarily notes.','Depositing does not establish control.','A deposit is not a dividend entitlement.'],'Keep liability and ownership separate.')]),prereq=[2,3,8])

transfer=number(10,'transfer','At an imaginary bank, account A holds {a} CFA francs and account B holds {b}. A transfers {x} to B within this same bank. No fees or new lending occur. What is their combined deposit balance afterwards?','a+b',
 {'u':{'int':[5,12]},'v':{'int':[2,8]},'w':{'int':[1,4]},'a':{'expr':'u*1000'},'b':{'expr':'v*1000'},'x':{'expr':'w*1000'}},['A ends with {a-x}; B ends with {b+x}.','Their sum is ({a} − {x}) + ({b} + {x}) = {answer} CFA francs.'],
 [('creation','a+b+x','The transfer moves an existing deposit; it does not add this amount to the combined balance.'),('loss','a+b-x','The recipient receives what the sender loses, so the combined balance does not shrink.')])
lesson(10,'Commercial banks: functions and payments','distinguish moving existing deposits from creating a deposit through lending',
 'bank claims, payment services and risk','balance-sheet entries and credit creation',
 'Commercial banks provide customer deposits, payments and credit, normally subject to banking rules and commercial constraints. A transfer within a bank reduces the sender’s deposit and increases the recipient’s deposit without itself increasing the combined balance. A new bank loan credited to a borrower’s account creates both a loan asset and a matching deposit liability. The bank still faces capital, liquidity, risk, profitability and settlement constraints. It does not create unlimited wealth or freely spend every customer liability as profit.',
 'A fictional Douala supplier receives a transfer from another customer at the same bank. Their combined balance is unchanged when no fees or lending occur. A separate loan credited by the bank increases a borrower’s deposit and debt together. A payment to another bank can require interbank settlement, which differs from merely relabelling balances within one bank.',
 'Identify the event: existing-balance transfer, new lending, principal repayment or fee. State the perspective and track both sides. Do not call every digital balance movement new money or assume a bank loan adds equal net wealth to its borrower.',[
 F('within-bank transfer','movement of an existing balance between customers of the same bank','Sender loses the amount that recipient gains.','Every transfer increases their combined deposits.','Without new lending or fees, this transfer leaves the combined total unchanged.'),
 F('loan-created deposit','a deposit credited alongside a new bank loan claim','The bank records an asset and matching deposit liability.','The borrower receives a deposit without any debt.','The new loan is also an obligation of the borrower.'),
 F('interbank settlement','settlement of obligations between different banks','A payment to another bank can require transfer of settlement funds.','A customer deposit and central-bank settlement reserves are identical accounts.','They concern different holders and claims.'),
 F('commercial constraint','a risk or resource condition limiting bank decisions','A proposed loan must be assessed for repayment and funding needs.','Banks can lend without limit because deposits can be recorded.','Capital, liquidity, demand and risk still constrain lending.')],transfer,prereq=[9])

balance=number(12,'equity','An invented bank reports reserves {r}, customer loans {l} and securities {s}, all CFA francs. Its only liabilities are deposits of {d}. Find equity.','r+l+s-d',
 {'a':{'int':[4,8]},'b':{'int':[10,20]},'c':{'int':[2,6]},'e':{'int':[1,3]},'r':{'expr':'a*1000'},'l':{'expr':'b*1000'},'s':{'expr':'c*1000'},'d':{'expr':'r+l+s-e*1000'}},
 ['Assets = reserves + loans + securities = {r+l+s}.','Equity = assets − liabilities = {r+l+s} − {d} = {answer} CFA francs.'],
 [('deposits','d','Deposits are the bank’s liability, not its residual equity.'),('assets','r+l+s','Total assets still include the claims financed by deposits.')])
lesson(12,'A commercial bank’s balance sheet','classify bank assets and liabilities and reconcile them with equity',
 'commercial-bank deposits, lending and risk','paired credit-creation entries and simplified expansion models',
 'A balance sheet records a position at a date. From the bank’s perspective, reserves, loans granted and securities held are assets. Customer deposits are liabilities because the bank owes them. Equity is assets less liabilities, so assets equal liabilities plus equity. A customer may view their deposit as an asset without making it an asset of the bank. Balancing the equation does not prove that every asset will be repaid or available for an immediate payment. The model omits other real reporting categories.',
 'Original bank record: reserves {5000}, loans {12000}, securities {3000}; deposits {18000}, equity {2000} CFA francs. Assets total {5000+12000+3000}; deposits plus equity total {18000+2000}. The same customer loan is an asset for the lender and a debt for the borrower. No actual bank statement is used.',
 'Fix the bank’s perspective, classify each line and sum assets. Subtract all stated liabilities for equity, then reconcile both sides. Do not add a loan’s borrower debt as a second liability of the lending bank. Separate a stock balance sheet from income during a period.',[
 F('bank asset','a resource or claim held by the bank','A granted customer loan is a claim on repayment.','Every loan granted is a liability of the lending bank.','It is a lender asset and borrower liability.'),
 F('bank liability','an obligation the bank owes to another party','Customer deposits are owed by the bank.','Deposits are always bank equity.','Deposit claims differ from owners’ residual interests.'),
 F('equity','the residual of assets after liabilities','Subtract deposits from the stated complete asset total.','Equity is the same as all assets without deducting liabilities.','The residual excludes claims owed to others.'),
 F('balance-sheet identity','assets equalling liabilities plus equity','Both sides reconcile in the invented record.','A balanced record proves there is no credit or liquidity risk.','The identity does not eliminate risk.')],balance,prereq=[9,10],figure=record_table('Invented bank balance sheet reconciles assets with liabilities and equity',[('Reserves','5000'),('Loans','12000'),('Securities','3000'),('Total assets','5000+12000+3000'),('Deposits','18000'),('Equity','2000'),('Liabilities + equity','18000+2000')]))

loan=number(13,'loan-entry','A fictional bank’s loan assets are {l} CFA francs before it grants and credits a new loan of {x}. No repayments, write-downs or other changes occur. What are its loan assets afterwards?','l+x',
 {'a':{'int':[10,30]},'b':{'int':[2,8]},'l':{'expr':'a*1000'},'x':{'expr':'b*1000'}},
 ['The new loan increases the bank’s claim on borrowers by {x}.','Loan assets become {l} + {x} = {answer} CFA francs; a matching deposit liability is created at origination.'],
 [('subtract','l-x','The granted loan adds to the lender’s loan claim in this case.'),('newonly','x','That omits the stated existing loan assets.')])
lesson(13,'Credit creation: the loan and deposit entry','trace a new bank loan and matching deposit without confusing money creation with wealth creation',
 'bank assets, liabilities and equity','the assumptions of the simplified deposit-expansion model',
 'When a bank grants a loan by crediting an account, it records a loan asset and matching deposit liability. The borrower has a new deposit asset and loan debt. This creates deposit money, not equal net wealth or new physical resources. Spending can move the deposit to another person or bank; settlement then matters. Repayment of principal from a deposit reduces both the loan and deposit in the simplified entry. Interest and fees are separate events. Real lending remains constrained by risk, capital, liquidity, demand and monetary conditions.',
 'Original new loan: {4000} CFA francs credited to a borrower. Bank loan assets rise by {4000}; deposit liabilities rise by {4000}; equity is unchanged by this principal-only entry. The borrower’s deposit and debt rise together. Subsequent transfer, interest and repayment need separate entries rather than being silently combined.',
 'Write the bank’s asset and liability changes, then the borrower’s asset and debt changes. Track the event and perspective before calculating. Do not say banks merely move a particular saver’s labelled notes or that recording a loan removes all lending limits.',[
 F('paired creation','a loan asset and deposit liability created together at origination','Granting and crediting the loan expands both sides.','A bank records only a free asset when it credits the borrower.','It also owes the new deposit.'),
 F('borrower debt','the obligation matching the borrower’s new loan funds','The borrower’s deposit rises alongside a repayment obligation.','A credited loan is a debt-free gift.','The loan remains repayable under its terms.'),
 F('principal repayment','a reduction of loan and deposit through the stated repayment entry','Principal paid from a deposit extinguishes that part of the loan and deposit.','Principal repayment necessarily creates an equal new loan.','The stated entry reduces, rather than originates, the claim.'),
 F('money versus wealth','the distinction between a monetary balance and net resources','A matching deposit and debt do not create equal net wealth.','Creating a deposit automatically creates a new physical machine.','A financial entry is not physical production.')],loan,prereq=[10,12])

MULT={'u':{'int':[2,9]},'r':{'pick':[10,20,25,50]},'D':{'expr':'u*10000'}}
multiplier=number(14,'total','Stylised closed banking model only: an outside reserve injection of {D} CFA francs becomes an initial deposit. Banks retain fraction {r}/{100} of every deposit; all remainder is lent and redeposited, with no cash leakage or excess reserves. What is the limiting total of deposits, including the initial deposit?','D*100/r',MULT,
 ['This is an assumed geometric expansion, not a forecast of real lending.','Total deposits = initial deposit / reserve fraction = {D} / ({r}/{100}) = {answer} CFA francs.','Additional model credit excludes the initial deposit: {D*100/r-D}.'],
 [('credit','D*100/r-D','That is additional model credit, excluding the initial deposit; the question asks total deposits.'),('reserve','D*r/100','That is the first-round retained reserve, not the limiting deposit total.')])
lesson(14,'Credit creation: a simplified expansion model and its limits','calculate a model deposit total and separate its assumptions from real bank lending',
 'paired loan/deposit entries and bank risk','guided model comparison in a Cameroon setting',
 'A traditional classroom model assumes an outside reserve injection becomes a deposit; banks retain a fixed fraction, lend the remainder and recipients redeposit it completely. With no leakages or excess reserves, the geometric deposit total is the initial deposit divided by the retained fraction. Additional model credit excludes the initial deposit. This is a stylised accounting model, not a mechanical description or prediction of real bank lending. Actual banks create deposits when lending and face demand, risk, capital, liquidity and monetary-policy conditions.',
 'Original model: initial deposit {10000} CFA francs, invented retained fraction {20}/{100}. Limiting deposits are {10000/(20/100)} and additional credit is {10000/(20/100)-10000}. These totals assume indefinite completion of the stated rounds. The fraction is not claimed to be a current BEAC rule or a lending recommendation.',
 'State the assumptions, convert the percentage to a fraction and identify whether total deposits or additional credit is requested. Do not confuse a limiting total with the result after a few rounds. Explain why actual credit cannot be predicted from this formula alone.',[
 F('retained fraction','the stipulated proportion held in each model round','The exercise states an invented fraction of each deposit.','The exercise fraction announces today’s BEAC reserve rule.','It is a hypothetical model parameter, not a current regulation.'),
 F('limiting deposit total','the sum approached by all assumed deposit rounds','Divide the initial deposit by the retained fraction.','The limiting total equals only the first loan.','The total includes the initial and later assumed deposits.'),
 F('additional model credit','the limiting deposit total less the initial deposit','Remove the starting deposit from the model total.','Additional credit and total deposits are always identical.','The initial deposit distinguishes them.'),
 F('model limitation','an assumption preventing automatic real-world prediction','Leakages, risk or weak borrowing demand can break the stipulated chain.','Actual lending must always equal the formula regardless of conditions.','The stylised assumptions need not hold in practice.')],multiplier,prereq=[9,12,13])

rounds=number(15,'rounds','Invented Cameroon classroom model: an initial deposit is {D} CFA francs and each bank retains {r}% of its received deposit. Each remaining amount is fully lent and redeposited at the next bank. Add only the initial deposit and the next two deposits; do not use the infinite total.','D+D*(1-r/100)+D*(1-r/100)*(1-r/100)',MULT,
 ['Initial deposit: {D}. Next deposit: {D*(1-r/100)}. Following deposit: {D*(1-r/100)*(1-r/100)}.','Finite sum = {answer} CFA francs.','This finite sum is below the stipulated limiting total {D*100/r}.'],
 [('infinite','D*100/r','That includes all indefinitely assumed rounds, not just the stated initial and next two deposits.'),('omit','D*(1-r/100)+D*(1-r/100)*(1-r/100)','That omits the initial deposit the question expressly includes.')])
lesson(15,'Practical preparation: credit-creation records in Cameroon','construct a finite deposit-round record and identify why it is not an observed lending total',
 'loan/deposit entries and the stylised multiplier','BEAC, central-bank functions and evidence-based interpretation',
 'Use fictional banks and invented CFA-franc amounts, not actual account details. Prepare columns for incoming deposit, stipulated retained fraction and next redeposit. Calculate each round from its predecessor. Compare a finite sum with the limiting model total. Record which assumptions permit the chain. A local currency or place name does not turn a hypothetical fraction into a Cameroon regulation or make the result an observed banking statistic.',
 'Original model banks A, B and C: deposit {10000}, retained fraction {20}/{100}. Subsequent deposits are {10000*(1-20/100)} and {10000*(1-20/100)*(1-20/100)}. The finite sum is {10000+10000*(1-20/100)+10000*(1-20/100)*(1-20/100)}; the limiting model total is {10000/(20/100)}. No real customers, banks or current reserve ratios are represented.',
 'Write assumptions above the table. Multiply by the fraction left after retention to find the next deposit. Add exactly the rounds requested. Explain how incomplete redepositing or a decision not to lend would change the assumed sequence; actual lending requires separate evidence.',[
 F('incoming deposit','the amount received for the current assumed round','Bank B receives the preceding round’s stipulated redeposit.','Every bank automatically starts again with the full original amount.','Each round follows the previous remainder in this model.'),
 F('next-round amount','the retained-fraction complement applied to the incoming deposit','Multiply the received deposit by the fraction not retained.','The retained amount itself is the whole next loan in this model.','The assumed next amount is the remainder.'),
 F('finite sum','the total of only the specified recorded rounds','Add the initial deposit and the next two when requested.','A finite record already includes every infinitely continuing round.','A limiting sum includes further assumed terms.'),
 F('local-evidence distinction','separation of a Cameroon-labelled model from a real institutional observation','CFA-franc labels do not establish a current regulatory fraction.','Writing Cameroon in the title proves the figures are official.','Official claims need actual applicable sources.')],rounds,prereq=[13,14],figure=record_table('Invented three-bank deposit-round record',[('Bank A deposit','10000'),('A retained','10000*20/100'),('Bank B deposit','10000*(1-20/100)'),('B retained','10000*(1-20/100)*20/100'),('Bank C deposit','10000*(1-20/100)*(1-20/100)'),('Finite deposit sum','10000+10000*(1-20/100)+10000*(1-20/100)*(1-20/100)')]))

lesson(16,'The central bank','distinguish monetary-policy and currency functions from commercial banking and fiscal decisions',
 'money, bank settlement and credit constraints','a guided case study of BEAC and public finance',
 'A central bank has system-wide monetary responsibilities, distinct from an ordinary commercial bank’s customer business. It can conduct monetary policy, issue currency under its framework and support settlement arrangements. Central-bank reserves used between banks differ from customer deposit balances. Policy influences monetary and credit conditions rather than producing goods directly. Government taxation and expenditure are fiscal decisions, not the same activity as monetary policy. Institutional mandates vary, so a general comparison must be checked against the central bank actually being studied.',
 'Cameroon shares BEAC with other CEMAC states. Its stated missions include monetary policy, banknote and coin issue, foreign-exchange reserves and payment-system functioning. A commercial bank’s decision to credit a customer loan is different from BEAC issuing currency. Neither a policy announcement nor an accounting entry supplies every physical resource the economy needs.',
 'Identify the institution and instrument before describing the effect. Separate cash issue, commercial-bank deposits and central-bank settlement balances. Distinguish government spending/tax decisions from monetary operations, and qualify any claim about policy outcomes.',[
 F('monetary policy','central-bank action influencing monetary and credit conditions','BEAC conducts monetary policy for its regional framework.','Monetary policy is identical to constructing every school building.','It influences financial conditions rather than directly producing every public service.'),
 F('currency issue','the provision of notes and coins under the monetary framework','BEAC has the regional currency-issue role described by its official source.','A commercial customer can issue BEAC notes by writing a cheque.','A payment instruction does not confer note-issue authority.'),
 F('settlement reserves','central-bank balances used in interbank settlement','Banks settle obligations through the applicable arrangements.','Customer deposits and each bank’s central-bank balance are the same account.','They are claims held at different institutional levels.'),
 F('fiscal distinction','separation of government revenue/spending from monetary policy','A public spending decision differs from a monetary-policy operation.','Every tax decision is made by an ordinary commercial-bank cashier.','Fiscal decisions are not that cashier’s monetary function.')],choose(16,[
 ('Which action is monetary rather than fiscal in this comparison?','A central-bank monetary-policy operation.',['A government vote on school spending.','A tax revenue decision.','A household grocery purchase.'],['That is public expenditure.','That is a fiscal revenue matter.','That is private consumption.'],'Identify the monetary institution and operation.'),
 ('Who has the official currency-issue role in the Cameroon/CEMAC case?','BEAC.',['Every commercial account holder.','Any pupil printing a classroom diagram.','Every shop issuing a receipt.'],['Holding an account does not confer that role.','A diagram is not currency issue.','Receipts are not legal currency issue.'],'The official BEAC source supplies the role.'),
 ('Why distinguish a commercial loan from central-bank note issue?','They create different kinds of monetary claims through different institutions.',['They must be the same physical action.','A commercial loan creates no obligation.','A note automatically records a private borrower’s new loan.'],['The institutional entries differ.','The loan is repayable.','A currency note is not that private loan contract.'],'Separate currency and bank-deposit mechanisms.'),
 ('What can a policy announcement alone establish?','The stated policy intention or decision, not every eventual outcome.',['A guarantee that all prices instantly fall.','A completed increase in every physical resource.','An identical effect on every household.'],['Outcomes are not immediate guarantees.','An announcement is not physical production.','Effects can differ by circumstance.'],'Keep policy and measured outcome distinct.')]),prereq=[7,9,13,15])

lesson(17,'Guided case study: BEAC as a central bank','use an official institutional description to assign roles and avoid unsupported policy claims',
 'central-bank and fiscal distinctions','public-finance foundations and later monetary analysis',
 'BEAC is the common central bank for Cameroon, Central African Republic, Congo, Gabon, Equatorial Guinea and Chad. Its official description assigns monetary policy, currency issue, exchange policy, official foreign-exchange reserves, payments functioning and financial-stability responsibilities. Its role is regional rather than a separate central bank serving only Cameroon. The source also describes resources supplied to COBAC for banking supervision; this is not a reason to erase the institutions’ distinct roles. This exercise uses the official description, not current rates or a policy forecast.',
 'Source-based classroom paraphrase, not a quotation: the official BEAC institutional page identifies a common central bank and its monetary responsibilities. In an invented sorting exercise, one card proposes a monetary-policy task, another names a government tax decision and a third describes a customer loan. Only the first directly matches the stated central-bank policy role. The exercise supplies no current reserve-ratio decision.',
 'Record source, institution, scope and the claim actually supported. Sort each invented task by role, then explain the evidence. Mark absent figures as unknown. Confirm current applicable decisions from their own official documents rather than extracting them from a general mission page.',[
 F('regional scope','BEAC serving the listed CEMAC states together','Cameroon is a member of the common central-bank area.','BEAC is a commercial bank serving only one town.','The official institutional scope is regional.'),
 F('mission evidence','support for an institutional role from the official description','The page assigns monetary-policy responsibilities to BEAC.','A mission list proves every policy objective has already been achieved.','A responsibility differs from its eventual performance.'),
 F('institutional distinction','separation of BEAC, COBAC and commercial-bank roles','The source distinguishes central-bank responsibilities and supervisory support.','Mentioning COBAC makes every institution identical.','Related responsibilities do not erase institutional identity.'),
 F('missing-decision limit','recognition that a general mission page does not supply every current parameter','The exercise gives no applicable current reserve fraction.','Any invented classroom fraction is an official current decision.','A current decision needs its applicable official source.')],choose(17,[
 ('A pupil calls BEAC Cameroon’s own town-level commercial bank. What should be corrected?','It is a common regional central bank, including Cameroon among its members.',['It is merely a customer’s personal account.','It has no monetary role.','The fictional class bank is its official name.'],['An institution differs from an account.','Monetary functions are stated.','The class examples are explicitly fictional.'],'Use the official institutional scope.'),
 ('Does the mission page prove inflation is already controlled in every period?','No; a responsibility does not establish every measured outcome.',['Yes, by definition of a mission.','Yes, without any price evidence.','No, therefore the institution cannot conduct policy.'],['Mandate and outcome differ.','Outcome claims need measurement.','Lack of outcome evidence does not erase the role.'],'Keep role evidence and performance evidence distinct.'),
 ('A class model uses retained fraction {20}/{100}. Is it an official current BEAC parameter?','Not from this exercise; it is expressly invented.',['Yes, because amounts are in CFA francs.','Yes, because Cameroon is named.','Yes, because the general mission page exists.'],['Currency units do not establish regulation.','A place name does not establish a decision.','General responsibilities do not supply this parameter.'],'Use a current applicable decision for a regulatory claim.'),
 ('Which task directly matches the stated monetary-policy role?','Conducting the common monetary policy.',['Choosing a household’s dinner.','Writing every pupil’s essay.','Giving every commercial borrower a guaranteed profit.'],['Private meals are not the assigned mission.','Education tasks are not this monetary role.','No institution can infer that guarantee from the mission.'],'Match the task to the supported role.')]),prereq=[16])

budget=number(19,'balance','An invented public-budget model has tax revenue {t} CFA francs, non-tax revenue {n} and expenditure {e}. Borrowing is financing, excluded from revenue here. Calculate revenue minus expenditure.','t+n-e',
 {'u':{'int':[10,20]},'v':{'int':[2,6]},'w':{'int':[8,28]},'t':{'expr':'u*1000'},'n':{'expr':'v*1000'},'e':{'expr':'w*1000'}},
 ['Revenue = tax plus non-tax receipts = {t+n}.','Balance = {t+n} − {e} = {answer} CFA francs. A negative result is a deficit in this stated model.'],
 [('expense','e','Expenditure alone is not the revenue-minus-expenditure balance.','e != t+n-e'),('alladd','t+n+e','Spending is subtracted in this balance rather than added as revenue.')])
budget['signed']=True
lesson(19,'Fundamental notions of public finance','distinguish public revenue, expenditure and financing and calculate a stated budget balance',
 'government/central-bank distinctions and financial records','later taxation, public spending and budget-policy analysis',
 'Public finance concerns government revenue, expenditure and financing. Taxes and non-tax receipts can provide revenue; borrowing finances a gap but is not counted as revenue in this stated model. Expenditure purchases services or assets and makes transfers under the applicable budget classification. Revenue minus expenditure gives a surplus if positive, a deficit if negative and balance if equal. A deficit is a flow during a period; public debt is a stock at a date. Fiscal choices differ from central-bank monetary policy.',
 'Original simplified public budget: tax receipts {12000}, non-tax receipts {3000} and expenditure {18000} CFA francs. Revenue is {12000+3000}; balance is {12000+3000-18000}. Borrowing that finances the gap does not turn the deficit into tax revenue. These tiny invented amounts teach a relationship, not a real Cameroon government budget or tax rule.',
 'Use the period and classification stated. Add revenue categories, subtract expenditure and interpret the sign. Keep financing and revenue separate, and distinguish an annual deficit from total debt. Real budgets require more detailed classifications than this introductory model.',[
 F('public revenue','tax and non-tax receipts included under the stated classification','The model combines taxes and its non-tax receipts.','Borrowing is automatically a tax receipt in this model.','It is financing rather than classified revenue here.'),
 F('public expenditure','spending included under the stated public-budget classification','The model records spending on public purposes and transfers.','Every expenditure is money earned by government.','Spending and revenue have different roles.'),
 F('budget balance','revenue less expenditure for the stated period','A negative result records a deficit in the model.','Adding expenditure to revenue gives this balance.','Expenditure is subtracted.'),
 F('stock-flow distinction','separation of a debt position from a period’s deficit','Debt is measured at a date; deficit over a period.','An annual deficit and total debt are always the same amount.','A stock and one period’s flow need not coincide.')],budget,prereq=[12,16,17])

